const out = {};
const dir = await fs.promises.opendir("d", { bufferSize: 2 });
out.path = dir.path; out.isDir = dir instanceof fs.Dir;
out.first = h.dirent(await dir.read());
out.viaCallback = await new Promise(resolve => { const order = []; const r = dir.read((e, d) => { order.push("callback"); resolve({ order, e, d: h.dirent(d), r }); }); order.push("returned"); });
const names = []; for await (const e of dir) names.push(e.name); out.rest = names;
out.afterIteration = await h.attemptAsync(() => dir.read());
const early = await fs.promises.opendir("d");
for await (const e of early) { out.early = e.name; break; }
out.earlyClosed = h.attempt(() => early.readSync());
// Concurrency: a pending asynchronous read refuses the synchronous forms and queues the others.
const busy = fs.opendirSync("d", { bufferSize: 1 });
const order = [];
const pending = busy.read().then(d => { order.push("read1:" + d.name); });
out.readSyncBusy = h.attempt(() => busy.readSync()); out.closeSyncBusy = h.attempt(() => busy.closeSync()); out.disposeBusy = h.attempt(() => busy[Symbol.dispose]());
const second = busy.read().then(d => { order.push("read2:" + d.name); });
const closing = busy.close().then(() => { order.push("closed"); });
await Promise.all([pending, second, closing]);
out.order = order;
const disposing = fs.opendirSync("d"); out.asyncDispose = await disposing[Symbol.asyncDispose](); out.afterAsyncDispose = h.attempt(() => disposing.readSync());
const viaClose = fs.opendirSync("d"); out.closeCallback = await new Promise(resolve => { const r = viaClose.close((...args) => resolve({ args, r })); });
const entries = fs.opendirSync("d").entries(); out.entriesFirst = (await entries.next()).value.name; out.entriesReturn = await entries.return(); 
return out;

