// tmpfs lists a directory newest first, so creating in descending name order gives the byte order the file service lists in.
fs.mkdirSync("d/sub", { recursive: true }); fs.symlinkSync("a.txt", "d/l"); fs.writeFileSync("d/b.txt", "b"); fs.writeFileSync("d/a.txt", "a");
const dir = fs.opendirSync("d");
const out = { path: dir.path, ctor: dir.constructor.name, isDir: dir instanceof fs.Dir, keys: Object.keys(dir), entries: [] };
for (let e; (e = dir.readSync()) !== null;) out.entries.push(h.dirent(e));
out.afterEnd = dir.readSync();
out.close = dir.closeSync();
out.readClosed = h.attempt(() => dir.readSync());
out.closeClosed = h.attempt(() => dir.closeSync());
out.readClosedAsync = h.attempt(() => dir.read(() => {}));
out.readClosedPromise = await h.attemptAsync(() => dir.read());
out.closeClosedPromise = await h.attemptAsync(() => dir.close());
out.closeClosedCallback = await new Promise(resolve => dir.close(e => resolve(h.err(e))));
out.dispose = h.attempt(() => dir[Symbol.dispose]());
out.asyncDispose = await h.attemptAsync(() => dir[Symbol.asyncDispose]());
const abs = fs.opendirSync("/work/d/");
out.absPath = abs.path; out.absFirst = h.dirent(abs.readSync()); abs[Symbol.dispose](); out.disposed = h.attempt(() => abs.readSync());
const url = fs.opendirSync(new URL("file:///work/d")); out.urlPath = url.path; url.closeSync();
const buf = fs.opendirSync(h.Buffer.from("d")); out.bufPath = h.Buffer.isBuffer(buf.path) ? { hex: buf.path.toString("hex") } : buf.path; out.bufFirst = h.dirent(buf.readSync()); buf.closeSync();
return out;
